  assign addtree2_add_cast_1 = {addtree_re_17[15], addtree_re_17};
  assign addtree2_add_temp = addtree2_add_cast + addtree2_add_cast_1;
  assign addtree_re_18 = ((addtree2_add_temp[16] == 1'b0) && (addtree2_add_temp[15] != 1'b0) ? 16'sb0111111111111111 :
              ((addtree2_add_temp[16] == 1'b1) && (addtree2_add_temp[15] != 1'b1) ? 16'sb1000000000000000 :
              $signed(addtree2_add_temp[15:0])));
  assign addtree2_add_cast_2 = {addtree_im_13[15], addtree_im_13};
  assign addtree2_add_cast_3 = {addtree_im_17[15], addtree_im_17};
  assign addtree2_add_temp_1 = addtree2_add_cast_2 + addtree2_add_cast_3;
  assign addtree_im_18 = ((addtree2_add_temp_1[16] == 1'b0) && (addtree2_add_temp_1[15] != 1'b0) ? 16'sb0111111111111111 :
              ((addtree2_add_temp_1[16] == 1'b1) && (addtree2_add_temp_1[15] != 1'b1) ? 16'sb1000000000000000 :
              $signed(addtree2_add_temp_1[15:0])));

  always @(posedge clk or posedge reset)
    begin : addtree_out_pipe2_process
      if (reset == 1'b1) begin
        addtree_re_19 <= 16'sb0000000000000000;
        addtree_im_19 <= 16'sb0000000000000000;
      end
      else begin
        if (enb) begin
          addtree_re_19 <= addtree_re_18;
          addtree_im_19 <= addtree_im_18;
        end
      end
    end

  assign RRC_Interpolation_Filter_out_re = addtree_re_19;

  assign RRC_Interpolation_Filter_out_im = addtree_im_19;

endmodule  // RRC_Interpolation_Filter

